-- Function: public.sp_update_platform_experience
-- Backup generated on 2026-10-25 20:34:13

CREATE OR REPLACE PROCEDURE public.sp_update_platform_experience(IN p_id uuid, IN p_title character varying, IN p_description text, IN p_category character varying, IN p_age_range_min_months integer, IN p_age_range_max_months integer, IN p_duration_minutes integer, IN p_instructions text, IN p_safety_notes text, IN p_dna_payload text, IN p_pricing_model character varying, IN p_price_amount numeric, IN p_currency character varying, IN p_publication_status character varying, IN p_ownership_type character varying, IN p_current_version integer, IN p_creator_attribution character varying)  LANGUAGE plpgsql AS $procedure$ BEGIN     UPDATE platform_experiences SET         title = p_title,         description = p_description,         category = p_category,         age_range_min_months = p_age_range_min_months,         age_range_max_months = p_age_range_max_months,         duration_minutes = p_duration_minutes,         instructions = p_instructions,         safety_notes = p_safety_notes,         dna_payload = p_dna_payload,         pricing_model = p_pricing_model,         price_amount = p_price_amount,         currency = p_currency,         publication_status = p_publication_status,         ownership_type = p_ownership_type,         current_version = p_current_version,         creator_attribution = p_creator_attribution,         updated_at = NOW()     WHERE id = p_id; END; $procedure$ ;
